-- Gerado por scripts/gerar-semente.ts. Conteúdo de exemplo inicial.
begin;
create temp table _semente as select $semente${"canteiros":[{"id":"c1","numero":1,"nome":"Aromáticas de sol","descricao":"Plantas de folhas firmes e perfume forte, que pedem sol o dia todo."},{"id":"c2","numero":2,"nome":"Ervas de cozinha e chá","descricao":"Folhas macias, usadas no tempero e em infusões caseiras."},{"id":"c3","numero":3,"nome":"Medicinais tradicionais","descricao":"Espécies presentes na tradição popular e estudadas pela ciência."}],"plantas":[{"slug":"hortela","nome_popular":"Hortelã","nome_cientifico":"Mentha spicata","autor_taxon":"L.","familia":"Lamiaceae","canteiro_id":"c2","categorias":["Aromática","Chá","Tempero"],"caracteristicas":["Aroma refrescante","Folha serrilhada","Caule quadrado"],"frase_impacto":"O cheiro da hortelã fica guardado em glândulas minúsculas na superfície da folha. Quando você esfrega a folha, elas se rompem e o aroma sai.","resumo":"Erva rasteira que se espalha rápido pelo canteiro. Folhas com borda serrilhada e caule quadrado, marca da família das lamiáceas.","conhecendo":{"curto":"Folhas verde-vivo, opostas e com borda serrilhada. O caule tem quatro lados: passe o dedo e sinta as quinas.","ampliado":"As flores são pequenas, lilases ou brancas, reunidas em espigas no topo dos ramos. A planta é perene: renasce dos ramos rasteiros, chamados estolões, que correm sob a terra."},"cultivo":{"curto":"Gosta de sol pela manhã e solo sempre úmido. Cresce rápido e invade os vizinhos, por isso vive bem em vaso ou canteiro separado.","ampliado":"Para fazer mudas, corte um ramo de 10 cm e deixe em um copo com água até surgirem raízes. Colher as folhas com frequência estimula a planta a brotar de novo."},"historia":{"curto":"Usada como tempero e chá desde a Antiguidade, chegou ao Brasil com os colonizadores europeus.","ampliado":"No Brasil, é presença comum em quintais e entra em receitas como o quibe e sucos refrescantes. Existem dezenas de espécies e híbridos de hortelã, o que gera muita confusão de nomes populares."},"experiencia":{"curto":"O aroma muda de intensidade conforme a folha é tocada: inteira, quase não cheira; amassada, o cheiro é imediato."},"atividade":"Feche os olhos. Esfregue uma folha entre os dedos por alguns segundos e aproxime do nariz.","perguntas":["Que lembrança esse aroma traz para você?","Como você descreveria a textura dessa folha?"],"psicologia":{"curto":"Aromas conhecidos costumam trazer lembranças com muita rapidez. Isso acontece porque o olfato tem ligação direta com áreas do cérebro ligadas à memória e à emoção."},"fontes":[{"titulo":"Ministério da Saúde. Formulário de Fitoterápicos da Farmacopeia Brasileira, 2ª ed.","url":"https://www.gov.br/anvisa/pt-br/assuntos/farmacopeia/formulario-fitoterapico","consultadoEm":"2026-11-17"}],"exemplo":true,"publicado":true},{"slug":"alecrim","nome_popular":"Alecrim","nome_cientifico":"Salvia rosmarinus","autor_taxon":"Spenn.","familia":"Lamiaceae","canteiro_id":"c1","categorias":["Aromática","Tempero"],"caracteristicas":["Aroma resinoso","Folha em agulha","Arbusto lenhoso"],"frase_impacto":"Até 2017 o alecrim tinha outro nome científico, Rosmarinus officinalis. Estudos de DNA mostraram que ele é, na verdade, uma sálvia.","resumo":"Arbusto de folhas finas como agulhas, verde-escuras por cima e esbranquiçadas por baixo. Perfume forte que fica nos dedos.","conhecendo":{"curto":"Folhas estreitas, duras e com a borda virada para baixo. Os ramos ficam lenhosos com o tempo.","ampliado":"As flores, pequenas e azul-claras, atraem abelhas. A face de baixo da folha tem uma penugem branca que reduz a perda de água, adaptação ao clima seco do Mediterrâneo, de onde a planta vem."},"cultivo":{"curto":"Sol pleno e pouca água. Encharcar o solo é a forma mais comum de perder um pé de alecrim.","ampliado":"Prefere solo arenoso e bem drenado. Multiplica-se por estacas de ramos semilenhosos."},"historia":{"curto":"Na Europa antiga, ramos de alecrim eram usados em casamentos e funerais como símbolo de lembrança."},"experiencia":{"curto":"A folha é áspera por cima e macia por baixo. O aroma aparece ao dobrar a folha ao meio."},"atividade":"Passe a ponta dos dedos pela folha nos dois sentidos, de cima para baixo e de baixo para cima.","perguntas":["Quais diferenças você percebe entre os dois lados da folha?"],"psicologia":{"curto":"Comparar texturas de olhos fechados aumenta a atenção ao tato, um sentido que usamos o tempo todo sem perceber."},"fontes":[{"titulo":"Ministério da Saúde. Formulário de Fitoterápicos da Farmacopeia Brasileira, 2ª ed.","url":"https://www.gov.br/anvisa/pt-br/assuntos/farmacopeia/formulario-fitoterapico","consultadoEm":"2026-11-17"}],"exemplo":true,"publicado":true},{"slug":"manjericao","nome_popular":"Manjericão","nome_cientifico":"Ocimum basilicum","autor_taxon":"L.","familia":"Lamiaceae","canteiro_id":"c2","categorias":["Aromática","Tempero"],"caracteristicas":["Aroma doce","Folha lisa e brilhante","Ciclo curto"],"frase_impacto":"Existem mais de 60 variedades de manjericão. Algumas têm cheiro de limão, outras de canela ou de cravo.","resumo":"Erva de folhas grandes, lisas e brilhantes. Vive pouco, mas cresce rápido e perfuma o canteiro inteiro em dias quentes.","conhecendo":{"curto":"Folhas ovais, macias e um pouco côncavas. Flores brancas em espigas no topo.","ampliado":"É uma planta anual: completa o ciclo em alguns meses. Quando floresce, as folhas perdem sabor, por isso quem cultiva costuma cortar as flores."},"cultivo":{"curto":"Sol e calor. Regue sem encharcar e corte as pontas para a planta ficar cheia."},"historia":{"curto":"Vem da Ásia tropical. Na Itália virou base do molho pesto; na Índia, uma espécie próxima, o tulsi, é planta sagrada."},"experiencia":{"curto":"O cheiro é doce e muda ao longo do dia: costuma ficar mais intenso nas horas quentes."},"atividade":"Cheire uma folha de manhã e outra à tarde. Se puder, compare.","perguntas":["Esse aroma lembra algum lugar ou comida para você?"],"psicologia":{"curto":"Cheiros ligados à comida costumam despertar lembranças de família e de casa. Cada pessoa tem as suas."},"fontes":[{"titulo":"Ministério da Saúde. Formulário de Fitoterápicos da Farmacopeia Brasileira, 2ª ed.","url":"https://www.gov.br/anvisa/pt-br/assuntos/farmacopeia/formulario-fitoterapico","consultadoEm":"2026-11-17"}],"exemplo":true,"publicado":true},{"slug":"lavanda","nome_popular":"Lavanda","nome_cientifico":"Lavandula angustifolia","autor_taxon":"Mill.","familia":"Lamiaceae","canteiro_id":"c1","categorias":["Aromática","Ornamental"],"caracteristicas":["Aroma floral","Flor roxa em espiga","Folha acinzentada"],"frase_impacto":"O nome lavanda vem do latim lavare, lavar. Os romanos perfumavam a água do banho com suas flores.","resumo":"Arbusto de folhas acinzentadas e flores roxas em espigas. O perfume está nas flores e também nas folhas.","conhecendo":{"curto":"Folhas estreitas, cobertas por pelos finos que dão a cor acinzentada. Flores pequenas e roxas, reunidas em espigas longas."},"cultivo":{"curto":"Sol pleno e solo seco. Em regiões muito quentes e úmidas, floresce menos.","ampliado":"Pede poda leve depois da floração para não ficar com os ramos de baixo secos."},"historia":{"curto":"Cultivada há séculos no sul da França, onde campos inteiros de lavanda viraram cartão-postal."},"experiencia":{"curto":"Cor, textura e aroma juntos: a espiga roxa, a folha aveludada e o perfume que fica nas mãos."},"atividade":"Observe a espiga de perto por um minuto. Conte quantas florzinhas você consegue ver.","perguntas":["Como você descreveria essa cor para alguém que não pode vê-la?"],"psicologia":{"curto":"Descrever uma cor em palavras exige atenção aos detalhes e mostra como cada pessoa percebe de um jeito."},"fontes":[{"titulo":"Ministério da Saúde. Formulário de Fitoterápicos da Farmacopeia Brasileira, 2ª ed.","url":"https://www.gov.br/anvisa/pt-br/assuntos/farmacopeia/formulario-fitoterapico","consultadoEm":"2026-11-17"}],"exemplo":true,"publicado":true},{"slug":"babosa","nome_popular":"Babosa","nome_cientifico":"Aloe vera","autor_taxon":"(L.) Burm.f.","familia":"Asphodelaceae","canteiro_id":"c3","categorias":["Medicinal tradicional","Suculenta"],"caracteristicas":["Folha carnuda","Gel transparente","Borda com espinhos"],"frase_impacto":"A folha da babosa guarda água em um gel transparente. É assim que ela sobrevive a longos períodos sem chuva.","resumo":"Suculenta de folhas grossas, com pequenos espinhos na borda. Por dentro, um gel transparente e pegajoso.","conhecendo":{"curto":"Folhas em roseta, grossas e cheias de gel. Espinhos macios na borda.","ampliado":"Entre a casca verde e o gel há uma camada de líquido amarelado, de cheiro e gosto fortes. Essa parte tem compostos diferentes do gel e exige cuidado."},"cultivo":{"curto":"Sol e pouca água. Regue só quando a terra estiver completamente seca."},"historia":{"curto":"Conhecida há milênios no norte da África e no Oriente Médio. No Brasil, é uma das plantas mais comuns em quintais."},"experiencia":{"curto":"Toque a folha por fora e veja como é firme e fria. Por dentro, o gel é escorregadio."},"atividade":"Com a ajuda de um monitor, compare a casca e o gel de uma folha já cortada.","perguntas":["Como você descreveria essa textura?"],"psicologia":{"curto":"Texturas inesperadas provocam reações diferentes: curiosidade em uns, estranhamento em outros. Todas são válidas."},"fontes":[{"titulo":"Ministério da Saúde. Formulário de Fitoterápicos da Farmacopeia Brasileira, 2ª ed.","url":"https://www.gov.br/anvisa/pt-br/assuntos/farmacopeia/formulario-fitoterapico","consultadoEm":"2026-11-17"}],"exemplo":true,"publicado":true},{"slug":"camomila","nome_popular":"Camomila","nome_cientifico":"Matricaria chamomilla","autor_taxon":"L.","familia":"Asteraceae","canteiro_id":"c3","categorias":["Medicinal tradicional","Chá"],"caracteristicas":["Aroma adocicado","Flor como pequena margarida","Miolo oco"],"frase_impacto":"Corte uma flor de camomila ao meio: o miolo amarelo é oco. É assim que ela se diferencia de outras flores muito parecidas.","resumo":"Planta delicada de flores parecidas com pequenas margaridas: pétalas brancas e miolo amarelo em forma de cone.","conhecendo":{"curto":"Folhas muito recortadas, quase como fios. Flores pequenas com miolo amarelo saliente.","ampliado":"O que parece uma flor é, na verdade, um conjunto de dezenas de flores minúsculas, característica da família das asteráceas, a mesma do girassol."},"cultivo":{"curto":"Prefere clima ameno. Semeia-se direto no canteiro, cobrindo pouco as sementes."},"historia":{"curto":"Um dos chás mais tomados no mundo. No Sul do Brasil, o Paraná é grande produtor."},"experiencia":{"curto":"O aroma lembra maçã para muitas pessoas. Para outras, lembra feno ou mel."},"atividade":"Cheire uma flor seca e uma fresca. Compare.","perguntas":["Que lembrança esse aroma traz para você?"],"psicologia":{"curto":"O hábito de preparar e tomar um chá pode ser um momento de pausa. O ritual em si já chama a atenção para o presente."},"fontes":[{"titulo":"Ministério da Saúde. Formulário de Fitoterápicos da Farmacopeia Brasileira, 2ª ed.","url":"https://www.gov.br/anvisa/pt-br/assuntos/farmacopeia/formulario-fitoterapico","consultadoEm":"2026-11-17"}],"exemplo":true,"publicado":true}],"usos":[{"planta":"hortela","nivel":"popular","texto":"Chá depois das refeições, tradição em muitas famílias brasileiras.","ordem":0},{"planta":"hortela","nivel":"hipotese","texto":"Se o aroma de hortelã influencia a atenção. Há estudos pequenos, ainda sem conclusão.","ordem":1},{"planta":"alecrim","nivel":"popular","texto":"Tempero de carnes e batatas; banhos e defumações em práticas tradicionais.","ordem":0},{"planta":"alecrim","nivel":"hipotese","texto":"Efeito do aroma sobre a memória. Os estudos existentes são pequenos e têm resultados variados.","ordem":1},{"planta":"manjericao","nivel":"popular","texto":"Tempero de molhos e saladas; chá caseiro.","ordem":0},{"planta":"lavanda","nivel":"popular","texto":"Sachês perfumados em gavetas e travesseiros.","ordem":0},{"planta":"lavanda","nivel":"hipotese","texto":"Se o aroma da lavanda ajuda no relaxamento. Há estudos, mas com métodos e resultados diferentes entre si.","ordem":1},{"planta":"babosa","nivel":"popular","texto":"Gel aplicado na pele e no cabelo.","ordem":0},{"planta":"babosa","nivel":"uso_reconhecido","texto":"O gel aparece em publicações oficiais de fitoterapia para uso externo. Detalhes e limites serão preparados pela equipe de Farmácia.","ordem":1},{"planta":"camomila","nivel":"popular","texto":"Chá calmante, especialmente à noite.","ordem":0},{"planta":"camomila","nivel":"uso_reconhecido","texto":"A infusão das flores consta no Formulário de Fitoterápicos da Farmacopeia Brasileira. Indicações e limites serão preparados pela equipe de Farmácia.","ordem":1}],"jogos":[{"slug":"mitos-e-verdades","titulo":"Mitos e verdades","descricao":"Aromaterapia, plantas e bem-estar: o que é mito, o que é verdade e o que é só em parte.","tipo":"mitos_verdades","ordem":0,"exemplo":true},{"slug":"sentidos-e-percepcao","titulo":"Sentidos e percepção","descricao":"Perguntas sobre os temas da estação Sentidos: memória, atenção e como percebemos o mundo.","tipo":"quiz","ordem":1,"exemplo":true}],"perguntas":[{"jogo":"mitos-e-verdades","enunciado":"Óleos essenciais são naturais, então não fazem mal.","opcoes":["Mito","Verdade","Em parte"],"correta":0,"feedback":"Natural não quer dizer inofensivo. Óleos essenciais são muito concentrados: podem irritar a pele e as vias respiratórias, e alguns são tóxicos se engolidos, especialmente por crianças e animais.","fonte_titulo":null,"fonte_url":null,"ordem":0},{"jogo":"mitos-e-verdades","enunciado":"Um cheiro pode trazer de volta lembranças muito antigas.","opcoes":["Mito","Verdade","Em parte"],"correta":1,"feedback":"Pesquisas mostram que lembranças trazidas por cheiros tendem a ser mais antigas, muitas vezes da infância, e mais carregadas de emoção do que as trazidas por palavras ou imagens.","fonte_titulo":"Willander, J., & Larsson, M. (2006). Smell your way back to childhood. Psychonomic Bulletin & Review, 13(2), 240–244.","fonte_url":"https://doi.org/10.3758/BF03193837","ordem":1},{"jogo":"mitos-e-verdades","enunciado":"Aromaterapia cura ansiedade.","opcoes":["Mito","Verdade","Em parte"],"correta":0,"feedback":"Alguns estudos investigam se certos aromas ajudam no relaxamento, com resultados variados. Nenhum aroma substitui o cuidado de um profissional de saúde mental. Se a ansiedade atrapalha seu dia a dia, procure ajuda profissional.","fonte_titulo":null,"fonte_url":null,"ordem":2},{"jogo":"mitos-e-verdades","enunciado":"Chá de planta medicinal pode ser tomado à vontade, porque é natural.","opcoes":["Mito","Verdade","Em parte"],"correta":0,"feedback":"Plantas medicinais têm substâncias ativas. Podem causar efeitos indesejados e interagir com medicamentos. Publicações oficiais, como o Formulário de Fitoterápicos, indicam modo de preparo, quantidade e por quanto tempo usar.","fonte_titulo":"Anvisa. Formulário de Fitoterápicos da Farmacopeia Brasileira, 2ª ed.","fonte_url":"https://www.gov.br/anvisa/pt-br/assuntos/farmacopeia/formulario-fitoterapico","ordem":3},{"jogo":"mitos-e-verdades","enunciado":"Duas pessoas podem sentir o mesmo cheiro de formas diferentes.","opcoes":["Mito","Verdade","Em parte"],"correta":1,"feedback":"Cada pessoa tem uma combinação própria de receptores olfativos. Um exemplo famoso é o coentro: para parte das pessoas, ele tem gosto e cheiro de sabão, e isso está ligado a uma variação genética.","fonte_titulo":"Eriksson, N. et al. (2012). A genetic variant near olfactory receptor genes influences cilantro preference. Flavour, 1, 22.","fonte_url":"https://doi.org/10.1186/2044-7248-1-22","ordem":4},{"jogo":"mitos-e-verdades","enunciado":"Ficar um tempo perto de plantas e áreas verdes ajuda a recuperar a atenção.","opcoes":["Mito","Verdade","Em parte"],"correta":2,"feedback":"Há uma teoria conhecida, a da Restauração da Atenção, e estudos que apoiam essa ideia. Mas os resultados variam conforme a pessoa, o lugar e o tempo. É uma possibilidade estudada, não uma regra.","fonte_titulo":"Kaplan, S. (1995). The restorative benefits of nature. Journal of Environmental Psychology, 15(3), 169–182.","fonte_url":"https://doi.org/10.1016/0272-4944(95)90001-2","ordem":5},{"jogo":"mitos-e-verdades","enunciado":"Toda planta que cresce numa horta pode ser comida ou usada em chá.","opcoes":["Mito","Verdade","Em parte"],"correta":0,"feedback":"Algumas plantas são tóxicas, e espécies diferentes podem ser muito parecidas. Por isso, na horta, nada deve ser provado sem orientação de um responsável.","fonte_titulo":null,"fonte_url":null,"ordem":6},{"jogo":"mitos-e-verdades","enunciado":"O ser humano tem só cinco sentidos.","opcoes":["Mito","Verdade","Em parte"],"correta":0,"feedback":"Além de visão, audição, olfato, paladar e tato, percebemos a posição do corpo (propriocepção), o equilíbrio e sinais internos como fome e batimentos do coração (interocepção).","fonte_titulo":null,"fonte_url":null,"ordem":7},{"jogo":"mitos-e-verdades","enunciado":"Cheirar grãos de café \"limpa\" o nariz entre um perfume e outro.","opcoes":["Mito","Verdade","Em parte"],"correta":0,"feedback":"É um costume comum em lojas de perfume, mas um estudo não encontrou vantagem do café sobre simplesmente cheirar o ar. Dar uma pausa costuma funcionar tão bem quanto.","fonte_titulo":"Grosofsky, A., Haupert, M. L., & Versteeg, S. W. (2011). An exploratory investigation of coffee and lemon scents and odor identification. Perceptual and Motor Skills, 112(2), 536–538.","fonte_url":null,"ordem":8},{"jogo":"mitos-e-verdades","enunciado":"Existem pessoas que não sentem cheiro nenhum.","opcoes":["Mito","Verdade","Em parte"],"correta":1,"feedback":"A perda total do olfato se chama anosmia. Pode ser de nascença ou acontecer depois de infecções, como gripes, ou de lesões. Na horta, essas pessoas exploram com o tato, a visão e a audição.","fonte_titulo":null,"fonte_url":null,"ordem":9},{"jogo":"sentidos-e-percepcao","enunciado":"Qual é a diferença entre sensação e percepção?","opcoes":["São a mesma coisa, com nomes diferentes","Sensação é captar o estímulo; percepção é o cérebro dar sentido a ele","Sensação é física; percepção só acontece na imaginação","Percepção vem antes da sensação"],"correta":1,"feedback":"Os órgãos dos sentidos captam o estímulo (sensação). O cérebro organiza e interpreta esse sinal usando experiências, expectativas e atenção (percepção).","fonte_titulo":null,"fonte_url":null,"ordem":0},{"jogo":"sentidos-e-percepcao","enunciado":"Qual sentido tem o caminho mais curto até áreas do cérebro ligadas à emoção e à memória?","opcoes":["Visão","Audição","Olfato","Tato"],"correta":2,"feedback":"O olfato se liga de forma direta a regiões como a amígdala e o hipocampo. Isso ajuda a explicar por que cheiros trazem lembranças tão vivas.","fonte_titulo":"Herz, R. S. (2016). The role of odor-evoked memory in psychological and physiological health. Brain Sciences, 6(3), 22.","fonte_url":"https://doi.org/10.3390/brainsci6030022","ordem":1},{"jogo":"sentidos-e-percepcao","enunciado":"Como se chama a percepção da posição do próprio corpo, mesmo de olhos fechados?","opcoes":["Propriocepção","Sinestesia","Interocepção","Visão periférica"],"correta":0,"feedback":"É a propriocepção que permite, por exemplo, encostar o dedo no nariz de olhos fechados. Interocepção é a percepção de sinais internos, como fome e batimentos do coração.","fonte_titulo":null,"fonte_url":null,"ordem":2},{"jogo":"sentidos-e-percepcao","enunciado":"O que melhor descreve a atenção plena?","opcoes":["Esvaziar a mente de todos os pensamentos","Prestar atenção ao momento presente, de propósito e sem julgar","Fazer várias coisas ao mesmo tempo com eficiência","Um tratamento que substitui a psicoterapia"],"correta":1,"feedback":"Não se trata de esvaziar a mente: pensamentos aparecem, e tudo bem. A ideia é notar o presente com curiosidade. Os exercícios da horta são educativos e não substituem acompanhamento psicológico.","fonte_titulo":null,"fonte_url":null,"ordem":3},{"jogo":"sentidos-e-percepcao","enunciado":"Por que este site nunca passa uma informação só pela cor?","opcoes":["Para economizar tinta na impressão","Porque as pessoas percebem as cores de formas diferentes, e algumas não distinguem certos tons","Porque cores deixam o site mais lento","É apenas uma escolha de estilo"],"correta":1,"feedback":"Parte das pessoas tem dificuldade em distinguir alguns tons, e quem usa leitor de tela não vê cores. Por isso os selos de evidência têm ícone, texto e cor juntos.","fonte_titulo":null,"fonte_url":null,"ordem":4},{"jogo":"sentidos-e-percepcao","enunciado":"Segundo a Teoria da Restauração da Atenção, ambientes naturais...","opcoes":["Exigem muito esforço de concentração","Prendem a atenção de forma suave, ajudando a atenção dirigida a descansar","Curam a falta de atenção","Não têm relação com a atenção"],"correta":1,"feedback":"A teoria propõe que a natureza atrai a atenção sem esforço, o que daria descanso à atenção que usamos para estudar e trabalhar. É uma proposta estudada, com resultados que variam.","fonte_titulo":"Kaplan, S. (1995). The restorative benefits of nature. Journal of Environmental Psychology, 15(3), 169–182.","fonte_url":"https://doi.org/10.1016/0272-4944(95)90001-2","ordem":5}],"textos":[{"chave":"o-que-sao","estacao":"sentidos","titulo":"O que são experiências sensoriais?","corpo":"","resumo":"Como os sentidos captam o mundo e como o cérebro transforma isso em percepção.","ordem":0,"exemplo":true,"dados":{"secoes":[{"titulo":"Sentir e perceber","texto":["Os órgãos dos sentidos captam estímulos: luz, sons, moléculas no ar, pressão na pele. Isso é a sensação.","O cérebro organiza esses sinais e dá sentido a eles, usando o que você já viveu, o que espera e o que está prestando atenção. Isso é a percepção.","Por isso, duas pessoas diante da mesma folha podem perceber coisas diferentes. As duas estão certas."]},{"titulo":"Mais do que cinco sentidos","texto":["Além de visão, audição, olfato, paladar e tato, o corpo percebe a própria posição (propriocepção), o equilíbrio e sinais internos, como fome e batimentos do coração (interocepção)."]},{"titulo":"Atenção: o filtro","texto":["Recebemos muito mais estímulos do que conseguimos notar. A atenção escolhe o que chega à consciência. Quando você decide cheirar uma folha com calma, está treinando esse filtro."]}],"experimente":{"titulo":"Um sentido de cada vez","introducao":"Escolha uma planta da horta, ou qualquer planta perto de você.","passos":[{"texto":"Olhe para ela e repare em três detalhes que você não tinha notado.","segundos":30},{"texto":"Feche os olhos e toque uma folha. Ela é lisa, áspera, macia, fria?","segundos":30},{"texto":"Esfregue a folha de leve e aproxime do nariz.","segundos":30},{"texto":"Abra os olhos. Qual sentido trouxe mais informação?"}]},"pergunta":"Qual sentido você mais usa no dia a dia sem perceber?","fontes":[{"titulo":"Goldstein, E. B. Sensação e Percepção. São Paulo: Cengage Learning.","consultadoEm":"2026-11-17"}]}},{"chave":"natureza","estacao":"sentidos","titulo":"A natureza e a experiência humana","corpo":"","resumo":"O que a pesquisa diz sobre o contato com ambientes naturais e a atenção.","ordem":1,"exemplo":true,"dados":{"secoes":[{"titulo":"Atenção que descansa","texto":["Tarefas como estudar ou trabalhar exigem atenção dirigida, aquela que precisa de esforço para se manter. Ela se cansa.","A Teoria da Restauração da Atenção, proposta por Rachel e Stephen Kaplan, sugere que ambientes naturais prendem a atenção de forma suave, sem esforço, e isso ajudaria a atenção dirigida a se recuperar."]},{"titulo":"O que a pesquisa diz, e o que não diz","texto":["Muitas pessoas relatam se sentir mais tranquilas depois de um tempo em contato com plantas e áreas verdes. Estudos investigam esse efeito, com resultados que variam conforme a pessoa, o lugar e o tempo de exposição.","Isso não transforma a horta em tratamento. Ela é um espaço de convivência, observação e aprendizado."]}],"experimente":{"titulo":"Cinco minutos na horta","introducao":"Se estiver no laboratório, sente perto de um canteiro. Se não, escolha uma janela com vista para o verde.","passos":[{"texto":"Deixe o celular de lado e apenas observe o movimento das folhas.","segundos":60},{"texto":"Repare nos sons ao redor. Quais são da natureza e quais não são?","segundos":60},{"texto":"Perceba como você se sente agora, sem julgar."}]},"pergunta":"Existe algum lugar com plantas que faz parte das suas memórias?","fontes":[{"titulo":"Kaplan, S. (1995). The restorative benefits of nature: Toward an integrative framework. Journal of Environmental Psychology, 15(3), 169–182.","url":"https://doi.org/10.1016/0272-4944(95)90001-2","consultadoEm":"2026-11-17"}]}},{"chave":"memoria-olfativa","estacao":"sentidos","titulo":"Memória olfativa","corpo":"","resumo":"Por que um cheiro pode trazer de volta uma lembrança antiga em um segundo.","ordem":2,"exemplo":true,"dados":{"secoes":[{"titulo":"Um atalho no cérebro","texto":["O olfato tem um caminho curto até regiões do cérebro ligadas à emoção e à memória, como a amígdala e o hipocampo.","Talvez por isso as lembranças trazidas por um cheiro costumam vir carregadas de emoção e, muitas vezes, são da infância."]},{"titulo":"Cada nariz, uma história","texto":["O mesmo aroma pode lembrar a cozinha da avó para uma pessoa e um consultório para outra. A lembrança depende da história de cada um, não da planta.","Algumas pessoas sentem cheiros com menos intensidade, ou não sentem. A experiência delas também faz parte da horta: tato, visão e som continuam disponíveis."]}],"experimente":{"titulo":"Caça às lembranças","introducao":"Funciona com qualquer planta aromática: hortelã, alecrim, manjericão, capim-limão.","passos":[{"texto":"Esfregue uma folha entre os dedos e cheire por alguns segundos.","segundos":20},{"texto":"Feche os olhos e espere. Deixe vir qualquer imagem, lugar ou pessoa.","segundos":40},{"texto":"Se quiser, registre no diário sensorial o que apareceu."}]},"pergunta":"Que lembrança um aroma já trouxe de volta para você?","fontes":[{"titulo":"Herz, R. S. (2016). The role of odor-evoked memory in psychological and physiological health. Brain Sciences, 6(3), 22.","url":"https://doi.org/10.3390/brainsci6030022","consultadoEm":"2026-11-17"},{"titulo":"Willander, J., & Larsson, M. (2006). Smell your way back to childhood: Autobiographical odor memory. Psychonomic Bulletin & Review, 13(2), 240–244.","url":"https://doi.org/10.3758/BF03193837","consultadoEm":"2026-11-17"}]}},{"chave":"cores-formas-texturas","estacao":"sentidos","titulo":"Cores, formas e texturas","corpo":"","resumo":"Observar e descrever: atividades para perceber detalhes e respeitar o olhar de cada um.","ordem":3,"exemplo":true,"dados":{"secoes":[{"titulo":"Ninguém vê a mesma cor","texto":["A percepção da cor depende da luz, do fundo ao redor e dos olhos de quem vê. Uma parte das pessoas, principalmente homens, tem dificuldade em distinguir alguns tons, como verde e vermelho.","Por isso, neste site, nenhuma informação é passada só pela cor."]},{"titulo":"Formas que se repetem","texto":["Folhas opostas, em espiral, em roseta; bordas lisas ou serrilhadas. Repare como as formas se repetem em plantas da mesma família."]},{"titulo":"Palavras para o tato","texto":["Aveludada, cerosa, áspera, pegajosa, crocante. Descrever uma textura em palavras é um exercício de atenção e de vocabulário."]}],"experimente":{"titulo":"Descreva para quem não vê","introducao":"Em dupla: uma pessoa fica de olhos fechados, a outra descreve uma folha.","passos":[{"texto":"Descreva só a forma da folha, sem dizer o nome da planta.","segundos":45},{"texto":"Agora descreva a cor, comparando com coisas do dia a dia.","segundos":45},{"texto":"Entregue a folha. A outra pessoa confere pelo tato se reconhece a descrição."}]},"pergunta":"Como você descreveria a textura da última folha que tocou?","fontes":[{"titulo":"Goldstein, E. B. Sensação e Percepção. São Paulo: Cengage Learning.","consultadoEm":"2026-11-17"}]}},{"chave":"atencao-plena","estacao":"sentidos","titulo":"Atenção plena","corpo":"","resumo":"Exercícios breves de observação consciente, guiados passo a passo.","ordem":4,"exemplo":true,"dados":{"secoes":[{"titulo":"O que é","texto":["Atenção plena é prestar atenção ao momento presente de propósito, com curiosidade e sem julgar o que aparece.","Os exercícios desta página são educativos e curtos. Eles não substituem acompanhamento psicológico. Se algo desconfortável surgir, você pode parar a qualquer momento."]}],"experimente":{"titulo":"Uma folha, três minutos","introducao":"Segure uma folha na mão, ou olhe para uma planta perto de você. O cronômetro guia cada passo.","passos":[{"texto":"Respire normalmente e apenas olhe para a folha, como se fosse a primeira vez.","segundos":45},{"texto":"Acompanhe com os olhos as nervuras, do centro até a borda.","segundos":45},{"texto":"Feche os olhos e sinta o peso e a temperatura da folha na mão.","segundos":45},{"texto":"Aproxime do nariz. Perceba o aroma, ou a ausência dele.","segundos":45},{"texto":"Abra os olhos. Note como você está agora. Não há resposta certa."}]},"pergunta":"O que você percebeu na folha que não tinha notado antes?","fontes":[{"titulo":"Kabat-Zinn, J. (2003). Mindfulness-based interventions in context: Past, present, and future. Clinical Psychology: Science and Practice, 10(2), 144–156.","url":"https://doi.org/10.1093/clipsy.bpg016","consultadoEm":"2026-11-17"}]}}]}$semente$::jsonb as j;

insert into canteiros (id, numero, nome, descricao)
select * from jsonb_to_recordset((select j->'canteiros' from _semente)) as x(id text, numero int, nome text, descricao text);

insert into plantas (slug, nome_popular, nome_cientifico, autor_taxon, familia, canteiro_id, categorias, caracteristicas,
  frase_impacto, resumo, conhecendo, cultivo, historia, experiencia, atividade, perguntas, psicologia, fontes, exemplo, publicado)
select * from jsonb_to_recordset((select j->'plantas' from _semente)) as x(slug text, nome_popular text, nome_cientifico text, autor_taxon text, familia text, canteiro_id text,
  categorias text[], caracteristicas text[], frase_impacto text, resumo text, conhecendo jsonb, cultivo jsonb, historia jsonb,
  experiencia jsonb, atividade text, perguntas text[], psicologia jsonb, fontes jsonb, exemplo boolean, publicado boolean);

insert into usos (planta, nivel, texto, ordem)
select planta, nivel::nivel_evidencia, texto, ordem from jsonb_to_recordset((select j->'usos' from _semente)) as x(planta text, nivel text, texto text, ordem int);

insert into jogos (slug, titulo, descricao, tipo, ordem, exemplo)
select * from jsonb_to_recordset((select j->'jogos' from _semente)) as x(slug text, titulo text, descricao text, tipo text, ordem int, exemplo boolean);

insert into quiz_perguntas (jogo, enunciado, opcoes, correta, feedback, fonte_titulo, fonte_url, ordem)
select * from jsonb_to_recordset((select j->'perguntas' from _semente)) as x(jogo text, enunciado text, opcoes text[], correta int, feedback text, fonte_titulo text, fonte_url text, ordem int);

insert into textos (chave, estacao, titulo, corpo, resumo, ordem, exemplo, dados)
select * from jsonb_to_recordset((select j->'textos' from _semente)) as x(chave text, estacao text, titulo text, corpo text, resumo text, ordem int, exemplo boolean, dados jsonb);

commit;
